  /** Data-plane endpoint. Falls back to `PANW_AI_GW_DATA_ENDPOINT`. */
  dataEndpoint?: string;
  /** Admin-plane endpoint. Falls back to `PANW_AI_GW_ADMIN_ENDPOINT`. */
  adminEndpoint?: string;
  /**
