   * const receipt = await gw.configs.create({
   *   name: 'vertex-airs',
   *   workspace_id: '16f7e90d-382a-4e78-b577-1b01eb5f8297',
   *   config: { retry: { attempts: 3 }, cache: { mode: 'simple' } },
   * });
