export class AIGatewayTelemetryClient {
  private readonly baseUrl: string;
  private readonly auth: AuthAdapter;
  private readonly numRetries: number;
  private readonly tsgId: string;

  constructor(opts: AIGatewayTelemetryClientOptions) {
    this.baseUrl = opts.baseUrl;
    this.auth = opts.auth;
    this.numRetries = opts.numRetries;
    this.tsgId = opts.tsgId;
  }

  /** Error counts by status code. @example `await gw.telemetry.errorCategoryTrends({ workspaceSlug: 'ws-dev', days: 1 });` */
  async errorCategoryTrends(opts: AIGatewayWindowOptions): Promise<ErrorCategoryTrendsResponse> {
    return this.chart('error-category-trends', opts, ErrorCategoryTrendsResponseSchema);
  }

  /** Error counts per status code in each time bucket. @example `await gw.telemetry.groupedErrors({ workspaceSlug: 'ws-dev', days: 1 });` */
  async groupedErrors(opts: AIGatewayWindowOptions): Promise<GroupedErrorsResponse> {
    return this.chart('grouped-errors', opts, GroupedErrorsResponseSchema);
  }

  /** Available analytics filter values; may contain sensitive metadata keys/identifiers. @example `await gw.telemetry.filterBoundaries({ workspaceSlug: 'ws-dev', days: 1 });` */
  async filterBoundaries(opts: AIGatewayWindowOptions): Promise<GatewayFilterBoundariesResponse> {
    const params = serializeWindow(this.tsgId, opts);
    // Unlike charts, the captured boundary route does not take organisationId.
    delete params.organisationId;
    return request({
      method: 'GET',
      baseUrl: this.baseUrl,
      path: '/analytics/filter-boundaries',
      params,
      responseSchema: GatewayFilterBoundariesResponseSchema,
      auth: this.auth,
      numRetries: this.numRetries,
      secretOperation: 'telemetry.filterBoundaries',
    });
  }

  /** @internal Shared GET for every `logs/charts/*` endpoint. */
  private chart<T>(
    metric: (typeof AI_GW_CHART_METRICS)[number],
    opts: AIGatewayWindowOptions,
    // `any` for Zod's def/input generics, mirroring RequestSpec.responseSchema — schemas
    // built with .passthrough() have input ≠ output and fail a stricter constraint.
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    schema: z.ZodType<T, any, any>,
    validatedParams?: Record<string, string>,
  ): Promise<T> {
    return request<T>({
      method: 'GET',
      baseUrl: this.baseUrl,
      path: `${AI_GW_CHARTS_PATH}/${metric}`,
      params: validatedParams ?? serializeWindow(this.tsgId, opts),
      responseSchema: schema,
      auth: this.auth,
      numRetries: this.numRetries,
    });
  }

  /**
   * Total and per-day spend. **Values are in cents.**
   * @param opts - Workspace slug, time window and verified trace, metadata, list and range filters.
   * @returns Cost series plus the period total, in cents.
   * @example
   * ```ts
   * import { AIGatewayClient } from '@cdot65/prisma-airs-sdk';
   * const gw = new AIGatewayClient();
   *
   * const cost = await gw.telemetry.cost({ workspaceSlug: 'ws-main-a-349e0e', days: 7 });
   * console.log(`$${(cost.data.total / 100).toFixed(2)}`); // => "$4110.83"
   * ```
   */
  async cost(opts: AIGatewayChartOptions): Promise<CostChartResponse> {
    return this.chart(
      'cost',
      opts,
      CostChartResponseSchema,
      serializeFilteredOptions(this.tsgId, opts),
    );
  }

  /**
   * Per-day request counts.
   * @param opts - Workspace slug, time window and verified trace, metadata, list and range filters.
   * @returns Request-count series plus the filtered period total.
   * @example
   * ```ts
   * import { AIGatewayClient } from '@cdot65/prisma-airs-sdk';
   * const gw = new AIGatewayClient();
   *
   * const r = await gw.telemetry.requests({ workspaceSlug: 'ws-main-a-349e0e' });
   * // r.data.total => 25746
   * ```
   */
  async requests(opts: AIGatewayRequestChartOptions): Promise<CountChartResponse> {
    return this.chart(
      'requests',
      opts,
      CountChartResponseSchema,
      serializeFilteredOptions(this.tsgId, opts),
    );
  }

  /**
   * Latency in milliseconds. Percentiles are returned per-bucket and for the period.
   * @param opts - Workspace slug, time window and verified trace, metadata, list and range filters.
   * @returns Latency series with p50/p90/p99; `data.total` is the period mean, not a sum.
   * The period mean and percentiles are null when the cohort has no matching requests.
   * @example
   * ```ts
   * import { AIGatewayClient } from '@cdot65/prisma-airs-sdk';
   * const gw = new AIGatewayClient();
   *
   * const l = await gw.telemetry.latency({ workspaceSlug: 'ws-main-a-349e0e' });
   * // l.data.p99 => 8329.14
   * ```
