export class OAuthClient {
  public readonly tokenEndpoint: string;
  private readonly clientId: string;
  private readonly clientSecret: string;
  private readonly tsgId: string;
  private readonly tokenBufferMs: number;
  private readonly onTokenRefresh?: (info: TokenInfo) => void;

  private accessToken: string | null = null;
  private expiresAt = 0;
  private pendingFetch: Promise<string> | null = null;

  constructor(opts: OAuthClientOptions) {
    this.clientId = opts.clientId;
    this.clientSecret = opts.clientSecret;
    this.tsgId = opts.tsgId;
    this.tokenEndpoint = opts.tokenEndpoint ?? DEFAULT_TOKEN_ENDPOINT;
    this.tokenBufferMs = opts.tokenBufferMs ?? DEFAULT_TOKEN_BUFFER_MS;
    this.onTokenRefresh = opts.onTokenRefresh;
  }

  /**
   * Get a valid access token, refreshing if needed.
   * @returns Bearer access token string.
   * @example
   * ```ts
   * import { OAuthClient } from '@cdot65/prisma-airs-sdk';
   * const oauth = new OAuthClient({ clientId: 'cid', clientSecret: 'secret', tsgId: '1234567890' });
   *
   * const token = await oauth.getToken();
   * // token => 'eyJhbGciOi...'  (cached until ~30s before expiry, then auto-refreshed)
   * ```
   */
  async getToken(): Promise<string> {
    if (this.accessToken && Date.now() < this.expiresAt - this.tokenBufferMs) {
      return this.accessToken;
    }

    if (this.pendingFetch) {
      return this.pendingFetch;
    }

    this.pendingFetch = this.fetchToken().finally(() => {
      this.pendingFetch = null;
    });

    return this.pendingFetch;
  }

  /**
   * Clear the cached token, forcing a fresh fetch on next call.
   * @example
   * ```ts
   * import { OAuthClient } from '@cdot65/prisma-airs-sdk';
   * const oauth = new OAuthClient({ clientId: 'cid', clientSecret: 'secret', tsgId: '1234567890' });
   *
   * oauth.clearToken();
   * oauth.getTokenInfo().hasToken; // => false; next getToken() triggers a fresh fetch
   * ```
   */
  clearToken(): void {
    this.accessToken = null;
    this.expiresAt = 0;
  }

  /**
   * Check if the current token has passed its expiry time. Returns true if no token exists.
   * @returns Whether the token is expired.
   * @example
   * ```ts
   * import { OAuthClient } from '@cdot65/prisma-airs-sdk';
   * const oauth = new OAuthClient({ clientId: 'cid', clientSecret: 'secret', tsgId: '1234567890' });
   *
   * oauth.isTokenExpired(); // => true (no token fetched yet)
   * await oauth.getToken();
   * oauth.isTokenExpired(); // => false
   * ```
   */
  isTokenExpired(): boolean {
    if (!this.accessToken) return true;
    return Date.now() >= this.expiresAt;
  }

  /**
   * Check if the token is within the pre-expiry buffer window.
   * Returns true if no token exists.
   * @param bufferMs - Custom buffer in ms. Defaults to the configured `tokenBufferMs`.
   * @returns Whether the token is expiring soon.
   * @example
   * ```ts
   * import { OAuthClient } from '@cdot65/prisma-airs-sdk';
   * const oauth = new OAuthClient({ clientId: 'cid', clientSecret: 'secret', tsgId: '1234567890' });
   * await oauth.getToken();
   *
   * oauth.isTokenExpiringSoon();        // => false (just fetched)
   * oauth.isTokenExpiringSoon(3_600_000); // => true (1h buffer larger than remaining TTL)
   * ```
   */
  isTokenExpiringSoon(bufferMs?: number): boolean {
    if (!this.accessToken) return true;
    const buffer = bufferMs ?? this.tokenBufferMs;
    return Date.now() >= this.expiresAt - buffer;
  }

  /**
   * Get a snapshot of the current token state without exposing the actual token value.
   * @returns Current {@link TokenInfo}.
   * @example
   * ```ts
   * import { OAuthClient } from '@cdot65/prisma-airs-sdk';
   * const oauth = new OAuthClient({ clientId: 'cid', clientSecret: 'secret', tsgId: '1234567890' });
   * await oauth.getToken();
   *
   * const info = oauth.getTokenInfo();
   * // info =>
   * // { hasToken: true, isValid: true, isExpired: false, isExpiringSoon: false,
   * //   expiresInMs: 86370000, expiresAt: 1717000000000 }
   * ```
   */
  getTokenInfo(): TokenInfo {
    const now = Date.now();
    const hasToken = this.accessToken !== null;
    const isExpired = !hasToken || now >= this.expiresAt;
    const isExpiringSoon = !hasToken || now >= this.expiresAt - this.tokenBufferMs;
    const expiresInMs = hasToken ? Math.max(0, this.expiresAt - now) : 0;
    return {
      hasToken,
      isValid: hasToken && !isExpiringSoon,
      isExpired,
      isExpiringSoon,
      expiresInMs,
      expiresAt: hasToken ? this.expiresAt : 0,
    };
  }

  private async fetchToken(): Promise<string> {
    const credentials = btoa(`${this.clientId}:${this.clientSecret}`);
    const body = new URLSearchParams({
      grant_type: 'client_credentials',
      scope: `tsg_id:${this.tsgId}`,
    });

    const attempt = deadline(30_000);
    let response: Response | undefined;
    try {
      try {
        response = await abortable<Response>(
          fetch(this.tokenEndpoint, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/x-www-form-urlencoded',
              Authorization: `Basic ${credentials}`,
            },
            body: body.toString(),
            signal: attempt.signal,
          }).then((received) => {
            // A fetch wrapper can settle after abortable() has released every waiter.
            if (attempt.signal.aborted) discardTokenResponse(received);
            return received;
          }),
          attempt.signal,
        );
      } catch (err) {
        throw new AISecSDKException(
          `Token request failed: ${(err as Error).message}`,
          ErrorType.OAUTH_ERROR,
        );
      }

      if (!response.ok) {
        let errorMsg: string;
        try {
          const errorBody = (await abortable(response.json(), attempt.signal)) as Record<
            string,
            unknown
          >;
          errorMsg =
            (errorBody.error_description as string) ??
            (errorBody.error as string) ??
            `Token request failed with status ${response.status}`;
        } catch {
          errorMsg = `Token request failed with status ${response.status}`;
        }
        throw new AISecSDKException(errorMsg, ErrorType.OAUTH_ERROR, {
          failureKind: 'http',
          statusCode: response.status,
        });
      }

      let payload: unknown;
      try {
        payload = await abortable(response.json(), attempt.signal);
      } catch {
        throw new AISecSDKException('Token response is not valid JSON', ErrorType.OAUTH_ERROR);
      }
      const parsed = OAuthTokenResponseSchema.safeParse(payload);
      if (!parsed.success) {
        throw new AISecSDKException(
          'Token response did not match the OAuth schema',
          ErrorType.OAUTH_ERROR,
        );
      }
      const data = parsed.data;
      this.accessToken = data.access_token;
      this.expiresAt = Date.now() + data.expires_in * 1000;

      if (this.onTokenRefresh) {
        try {
          this.onTokenRefresh(this.getTokenInfo());
        } catch {
          // Don't let callback errors block token delivery
        }
      }

      return this.accessToken;
    } catch (error) {
      if (attempt.signal.aborted) {
        if (response) discardTokenResponse(response);
        throw new AISecSDKException('Token request timed out', ErrorType.OAUTH_ERROR, {
          failureKind: 'network',
        });
      }
      throw error;
    } finally {
      attempt.dispose();
    }
  }
}

