      requestSchema: AdapterUpdateRequestSchema,
      method: 'PUT',
      baseUrl: this.baseUrl,
      path: `${RED_TEAM_ADAPTER_PATH}/${uuid}`,
      params: { validate: String(validate) },
      body,
      responseSchema: AdapterResponseSchema,
      auth: this.auth,
      numRetries: this.numRetries,
    });
  }

